     1	/**
     2	 * How MHPCO settles a damage report against a policy.
     3	 *
     4	 * This module owns the office's claims rulings: what it deducts from every
     5	 * damage event and what it is willing to reimburse. It knows nothing about
     6	 * premiums — a policy costs what it costs, and a claim pays what it pays.
     7	 */
     8	
     9	import { type Item } from "./item.js";
    10	
    11	/** A single damaged item in a damage report. */
    12	export interface Damage {
    13	  readonly itemType: string;
    14	  readonly amount: number;
    15	}
    16	
    17	/** A damage report submitted against a policy. */
    18	export interface Incident {
    19	  readonly cause: string;
    20	  readonly damages: readonly Damage[];
    21	}
    22	
    23	/**
    24	 * MHPCO reimburses damage to a highly enchanted item at half its amount: such
    25	 * an item is held to be beyond the office's ordinary means of restoration.
    26	 */
    27	const HALF_REIMBURSEMENT_FROM_ENCHANTMENT = 8;
    28	const HALF = 0.5;
    29	
    30	/** MHPCO reimburses the whole damage amount when no clause reduces it. */
    31	const FULL_SHARE = 1;
    32	
    33	/** The share of a damage amount MHPCO accepts before taking its deductible. */
    34	function acceptedShare(damagedItem: Item): number {
    35	  return (damagedItem.enchantment ?? 0) >= HALF_REIMBURSEMENT_FROM_ENCHANTMENT
    36	    ? HALF
    37	    : FULL_SHARE;
    38	}
    39	
    40	/**
    41	 * MHPCO will never pay out more than twice what a policy insures in total,
    42	 * however many claims are made against it.
    43	 */
    44	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
    45	
    46	/** The total MHPCO is willing to pay out over the life of a policy. */
    47	function payoutCap(insuranceSum: number): number {
    48	  return insuranceSum * CAP_MULTIPLE_OF_INSURANCE_SUM;
    49	}
    50	
    51	/** How much of a reimbursement the cap lets through, and what is left of it. */
    52	export interface CappedPayout {
    53	  readonly payout: number;
    54	  readonly remainingCap: number;
    55	}
    56	
    57	/**
    58	 * Holds a reimbursement to what the policy's cap still allows: the office pays
    59	 * the lesser of what it owes and what its cap permits, and the rest of the cap
    60	 * stands available to later claims.
    61	 */
    62	export function capPayout(reimbursement: number, insuranceSum: number): CappedPayout {
    63	  const cap = payoutCap(insuranceSum);
    64	  const payout = Math.min(reimbursement, cap);
    65	  return { payout, remainingCap: cap - payout };
    66	}
    67	
    68	/** MHPCO deducts a fixed excess from every damage event it settles. */
    69	const DEDUCTIBLE_G = 100;
    70	
    71	/**
    72	 * What MHPCO reimburses for a single damaged item: the share of the damage its
    73	 * clauses accept, less the deductible it keeps on every damage event.
    74	 */
    75	export function damageReimbursement(damage: Damage, damagedItem: Item): number {
    76	  return damage.amount * acceptedShare(damagedItem) - DEDUCTIBLE_G;
    77	}

